import "core-js/modules/es.array.push.js";
import "core-js/modules/es.iterator.constructor.js";
import "core-js/modules/es.iterator.for-each.js";
/* eslint-disable */
import { create_list_edit_territories } from "@/graphql/mutations.js";
import { API, graphqlOperation } from "aws-amplify";
import { get_all_org_users } from "@/mixins/GetUsersDropdown.js";
export default {
  props: {
    editTerritoryDialogue: Boolean,
    rowInfo: Object
  },
  mixins: [get_all_org_users],
  data() {
    return {
      loading: false,
      territoryName: "",
      territoryCity: "",
      terriotoryManager: "",
      changedManager: false,
      userArray: [],
      searchF: ""
    };
  },
  watch: {
    editTerritoryDialogue: {
      async handler() {
        if (this.editTerritoryDialogue == true) {
          this.$store.commit("Setnamesearch", "");
          await this.get_all_org_users();
          this.changedManager = false, this.territoryName = this.rowInfo.territory_name;
          this.terriotoryManager = this.rowInfo.territory_head;
          await this.fetch_details();
        }
      },
      immediate: true
    }
  },
  methods: {
    fetch_details() {
      this.orgUsers.forEach(element => {
        if (element.user_status == "ACTIVE") {
          this.userArray.push({
            full_user_name: element.full_user_name,
            user_id: element.user_id
          });
        }
      });
    },
    close_dialog() {
      this.$emit("clicked", 0);
      //   this.$refs.form.resetValidation();
      //   this.$refs.form.reset();
    },
    change_manager() {
      this.changedManager = true;
    },
    validate_data() {
      if (this.$refs.form.validate()) {
        this.edit_mutation();
      }
    },
    async edit_mutation() {
      var data = this.$store.getters.GetUserObj;
      this.loading = true;
      try {
        let result = await API.graphql(graphqlOperation(create_list_edit_territories, {
          input: {
            organization_id: data.organization.organization_id,
            action_type: "UPDATE",
            territory_id: this.rowInfo.territory_id,
            territory_name: this.territoryName,
            territory_head: this.changedManager == true ? this.terriotoryManager.user_id : this.rowInfo.territory_head,
            territory_head_name: this.changedManager == true ? this.terriotoryManager.full_user_name : this.rowInfo.territory_head_name
          }
        }));
        this.loading = false;
        var response = JSON.parse(result.data.create_list_edit_territories);
        this.loading = false;
        if (response.Status == "SUCCESS") {
          this.$emit("successMsg", response.Message);
        } else {
          this.$emit("errorMsg", response.Message);
        }
      } catch (error) {
        this.loading = false;
        this.$emit("errorMsg", error.errors[0].message);
      }
    }
  }
};
